fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    // Since we're guaranteed that `a` and `b` have the same length
    // and each character is either '0' or '1', we can directly zip them.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(ac, bc)| if ac == bc { '0' } else { '1' })
     .collect()
}

